:root {
  --paper: #fffdf5;
  --ink: #28342a;
  --muted: #6f7869;
  --line: #d9dfcc;
  --moss: #426b50;
  --lichen: #e4eed6;
  --amber: #d97132;
  --cream: #fff3ce;
}

.foray-card {
  width: 480px;
  overflow: hidden;
  border: 1px solid var(--line);
  border-radius: 18px;
  background: var(--paper);
  color: var(--ink);
}

.card-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 14px 18px 12px;
  border-bottom: 1px solid var(--line);
}

.eyebrow {
  margin: 0 0 3px;
  color: var(--moss);
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

h1 {
  margin: 0;
  font-size: 22px;
  line-height: 1;
  letter-spacing: -0.04em;
}

.header-mark {
  padding: 5px 8px;
  border: 1px solid var(--moss);
  border-radius: 5px;
  color: var(--moss);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.08em;
}

.specimen-grid {
  display: grid;
  grid-template-columns: 126px 1fr;
  gap: 16px;
  padding: 15px 18px;
}

.specimen-visual {
  display: flex;
  align-items: center;
  justify-content: center;
  position: relative;
  margin: 0;
  border-radius: 12px;
  background: var(--lichen);
}

.cap {
  position: absolute;
  top: 31px;
  width: 72px;
  height: 37px;
  border-radius: 72px 72px 14px 14px;
  background: var(--amber);
}

.stem {
  width: 25px;
  height: 51px;
  margin-top: 39px;
  border-radius: 7px 7px 11px 11px;
  background: var(--cream);
}

.specimen-details {
  min-width: 0;
}

.latin {
  margin: 1px 0 10px;
  color: var(--moss);
  font-size: 14px;
  font-weight: 700;
  font-style: italic;
}

.detail-list {
  display: grid;
  gap: 5px;
  margin: 0;
  padding: 0;
  list-style: none;
}

.detail-list li {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 12px;
  font-size: 12px;
  line-height: 1.25;
}

.detail-list span {
  color: var(--muted);
}

.detail-list strong {
  color: var(--ink);
  font-weight: 700;
  text-align: right;
}

.status-row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 18px;
  border-top: 1px solid var(--line);
  background: var(--cream);
}

.status {
  padding: 4px 7px;
  border-radius: 999px;
  background: var(--moss);
  color: var(--paper);
  font-size: 10px;
  font-weight: 800;
  letter-spacing: 0.06em;
}

.route {
  flex: 1;
  color: var(--muted);
  font-size: 12px;
  font-weight: 600;
}

button {
  padding: 6px 10px;
  border: 1px solid var(--moss);
  border-radius: 7px;
  background: var(--paper);
  color: var(--moss);
  font-size: 12px;
  font-weight: 700;
}
